(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.035-t*0.5)*8 + Math.cos((y+wy1)*0.03+t*0.4)*6;
  const wy2 = Math.cos((y+wy1)*0.035+t*0.45)*8 + Math.sin((x+wx1)*0.028-t*0.55)*6;
  const sx = x + wx1 + wx2, sy = y + wy1 + wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.7],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.6],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.5],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.75],
    [80+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.5+4)*40, 0.14, 1.3, 0.65],
    [400+Math.cos(t*0.45+2)*70, 200+Math.sin(t*0.65+1)*50, 0.11, 2.1, 0.85]
  ];
  let aS = 0, iS = 0, wS = 0, wT = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    wS += Math.sin(d*f*1.3 - t*sp*0.4 + 3.0) * w * 0.5;
    wT += w;
  }
  const act = aS/wT, inh = iS/wT, wave = wS/wT;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const hx = sx*0.06, hy = sy*0.06;
  const hex = (Math.sin(hx*1.732+t*0.3) + Math.sin(hy*1.5+t*0.25) + Math.sin((hx*1.732-hy)*0.5+t*0.35))/3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
