  const sp2 = (Math.sin(dist*0.08+ang*2-t*0.8) + Math.cos(dist*0.06-ang*5+t*1.0))*0.2;
  const r1 = Math.tanh((act - inh*0.7 + (bg1+bg2)*0.3 + sp1)*2.2);
  const r2 = Math.tanh((wave - act*0.5 + hex*0.4 + sp2)*1.8);
  const comb = r1*0.65 + r2*0.35;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const grain = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.4-t*2.5)*0.08;
  const v = (comb*0.7 + cell*0.2 + grain*0.1)*0.5+0.5;
  const pal = [[5,10,45],[12,45,85],[18,90,120],[25,140,130],[120,175,95],[210,185,60],[220,130,55],[195,75,60],[140,40,55],[70,18,45],[5,10,45]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
